push.css:
.fxs .nn{--pr:16px;--pushA:#FF2BD6;--pushB:#0B0618;--pushC:#2EEBFF;--rim:#1A0F33;--rimD:#0B0618;
  --pushFace:linear-gradient(180deg,#140A2A,#0D0720)}
.fxs .push.nn{box-shadow:0 0 0 8px var(--rim),0 0 0 13px var(--rimD),0 10px 0 13px #05030C,0 0 26px 14px rgba(46,235,255,.32),0 22px 34px rgba(0,0,0,.5)}
.fxs .push.nn span{color:transparent;text-shadow:none}
.fxs .push.nn::after{border-color:rgba(46,235,255,.9)}
.fxs .nn .nnf{position:absolute;left:0;top:0;width:200px;height:100px;border-radius:16px;overflow:hidden;pointer-events:none;font-style:normal}
.fxs .nn .nnf svg{display:block;width:200px;height:100px}
.fxs .nn .nnd{position:absolute;left:-34px;top:-40px;width:268px;height:180px;pointer-events:none;z-index:3;font-style:normal}
.fxs .nn .nnd svg{display:block;width:268px;height:180px;overflow:visible}
.fxs .nn .nnt{transform-box:view-box;transform-origin:0 0}
.fxs .nn .nnh{animation:fxnnHum 2.4s ease-in-out infinite}
@keyframes fxnnHum{0%,100%{opacity:1}50%{opacity:.86}}
.fxs .nn .nnS{animation:fxnnFlick 5s linear infinite}
@keyframes fxnnFlick{0%,70%,73%,76%,100%{opacity:1}71.5%{opacity:.4}74.5%{opacity:.55}}
.fxs .nn .nnc{animation:fxnnChase 2.6s linear infinite}
@keyframes fxnnChase{from{stroke-dashoffset:0}to{stroke-dashoffset:-523.4}}
.fxs .nn .nnt{animation:fxnnTw 1.8s ease-in-out infinite}
@keyframes fxnnTw{0%,100%{transform:scale(.7);opacity:.6}50%{transform:scale(1.1);opacity:1}}
.fxs .nn .nnz{animation:fxnnHum 1.6s ease-in-out infinite}
.fxs .tap.nn{color:#2EEBFF;text-shadow:0 0 6px rgba(46,235,255,.8)}
.fxs .pressed.nn{border-radius:16px;box-shadow:0 0 0 8px var(--rim),0 0 0 13px var(--rimD),0 10px 0 13px #05030C,0 0 26px 14px rgba(46,235,255,.32);animation-name:fxnnPress,fxfxH}
@keyframes fxnnPress{0%{transform:scale(1)}35%{transform:scale(.84);filter:brightness(1.3)}100%{transform:scale(1.75);opacity:0;filter:brightness(1.5)}}
.fxs .clips.nn{position:absolute;z-index:4;left:50%;top:calc(50% - 40px);width:0;height:0}
.fxs .clips.nn i{position:absolute;opacity:0;animation:fxnnFly 1.25s cubic-bezier(.15,.7,.3,1) var(--d) both}
.fxs .clips.nn .tb{left:calc(var(--z) / -2);top:-2px;width:var(--z);height:4px;border-radius:2px;background:#FFFFFF;
  box-shadow:0 0 0 1.5px var(--c),0 0 8px 2px var(--c),0 0 16px 3px var(--c)}
.fxs .clips.nn .rg{left:calc(var(--z) / -2);top:calc(var(--z) / -2);width:var(--z);height:var(--z);border-radius:50%;border:2px solid #FFFFFF;
  box-shadow:0 0 0 1.5px var(--c),0 0 8px 2px var(--c),inset 0 0 6px var(--c)}
@keyframes fxnnFly{0%{opacity:0;transform:translate(0,0) rotate(0) scale(.3)}10%{opacity:1}55%{opacity:1;transform:translate(var(--x),var(--y)) rotate(var(--r)) scale(1)}
  100%{opacity:0;transform:translate(calc(var(--x) * 1.1),calc(var(--y) + 46px)) rotate(calc(var(--r) * 1.4)) scale(.6)}}
@media (prefers-reduced-motion:reduce){.fxs .nn .nnh,.fxs .nn .nnS,.fxs .nn .nnc,.fxs .nn .nnt,.fxs .nn .nnz{animation:none}
.fxs .nn .nnc{display:none}
.fxs .clips.nn{display:none}}
/* 設定の「演出を控えめにする」＝視差効果を減らすと同じ形（16.6） */
.fxs.calm .nn .nnh,.fxs.calm .nn .nnS,.fxs.calm .nn .nnc,.fxs.calm .nn .nnt,.fxs.calm .nn .nnz{animation:none}
.fxs.calm .nn .nnc{display:none}
.fxs.calm .clips.nn{display:none}

